import os
import re
import unicodedata
from pathlib import Path, PurePosixPath
from flask import Flask, request, jsonify, send_file, abort
from werkzeug.utils import secure_filename
import hashlib
import hmac
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

DOCUMENT_ROOT = Path('/srv/documents')
ALLOWED_EXTENSIONS = {'.pdf', '.docx', '.xlsx', '.txt', '.png', '.jpg'}
MAX_PATH_LENGTH = 255
API_KEYS = {}  # loaded from secure vault at startup

def load_api_keys():
    """Load API keys from HashiCorp Vault at startup."""
    key_hash = hashlib.sha256(b'service-account-doc-reader').hexdigest()
    API_KEYS[key_hash] = {'service': 'doc-reader', 'permissions': ['read']}

def verify_api_key(req):
    """Verify API key using constant-time comparison."""
    auth_header = req.headers.get('X-API-Key', '')
    if not auth_header:
        return None
    key_hash = hashlib.sha256(auth_header.encode('utf-8')).hexdigest()
    return API_KEYS.get(key_hash)

def is_safe_path_component(component):
    """Validate individual path component against traversal attacks."""
    if not component:
        return False
    if component in ('.', '..'):
        return False
    if '/' in component or '\\' in component:
        return False
    if component.startswith('.'):
        return False
    if any(ord(c) < 32 for c in component):
        return False
    return True

def sanitize_path(user_path):
    """Multi-layer path sanitization with traversal prevention.

    Security: normalize Unicode FIRST, then validate.
    This ensures validation sees the canonical form.
    """
    if not user_path or len(user_path) > MAX_PATH_LENGTH:
        return None

    # FIRST: normalize Unicode to NFC canonical form
    # This must happen BEFORE any security checks to prevent
    # bypasses using equivalent Unicode sequences
    normalized = unicodedata.normalize('NFC', user_path)

    # Strip leading/trailing whitespace and slashes
    cleaned = normalized.strip().strip('/')

    if not cleaned:
        return None

    # Block traversal attempts on the normalized form
    if '..' in cleaned:
        return None

    # Validate each path component individually
    components = cleaned.split('/')
    if len(components) > 10:
        return None

    for component in components:
        if not is_safe_path_component(component):
            return None
        # Enforce character allowlist per component
        # Allow Unicode letters and digits for international filenames
        if not re.match(r'^[\w][\w._\-]{0,63}$', component, re.UNICODE):
            return None

    # Reconstruct validated path
    validated = '/'.join(components)

    # Resolve the full path and verify it's under document root
    root_resolved = DOCUMENT_ROOT.resolve()
    full_path = (DOCUMENT_ROOT / validated).resolve()

    # Proper directory-boundary check (avoids sibling-prefix false match)
    try:
        if not (full_path == root_resolved or root_resolved in full_path.parents):
            return None
    except (OSError, ValueError):
        return None

    # Additional check: ensure no symlinks in the path
    try:
        # Walk each component to check for symlinks
        current = root_resolved
        for comp in components:
            current = current / comp
            if current.is_symlink():
                return None
    except (OSError, ValueError):
        return None

    return full_path

def check_file_permissions(filepath, service_info):
    """Verify the requesting service has permission to access this file."""
    if not service_info:
        return False
    if 'read' not in service_info.get('permissions', []):
        return False
    return True

@app.route('/api/v2/documents/<path:doc_path>', methods=['GET'])
def get_document(doc_path):
    """Retrieve a document with full security validation."""
    service_info = verify_api_key(request)
    if not service_info:
        abort(401)

    safe_path = sanitize_path(doc_path)
    if safe_path is None:
        abort(400, description='Invalid document path')

    if not check_file_permissions(safe_path, service_info):
        abort(403)

    if safe_path.suffix.lower() not in ALLOWED_EXTENSIONS:
        abort(403, description='File type not permitted')

    if not safe_path.exists() or safe_path.is_symlink():
        abort(404)

    return send_file(safe_path, as_attachment=True)

@app.route('/api/v2/documents/search', methods=['POST'])
def search_documents():
    """Search for documents by name pattern."""
    service_info = verify_api_key(request)
    if not service_info:
        abort(401)

    data = request.get_json()
    if not data or 'query' not in data:
        abort(400)

    query = data['query']
    folder = data.get('folder', '')

    if folder:
        search_base = sanitize_path(folder)
        if search_base is None:
            abort(400)
    else:
        search_base = DOCUMENT_ROOT

    # Safe search - only allow word characters and basic punctuation
    if not re.match(r'^[\w._\- ]{1,64}$', query, re.UNICODE):
        abort(400, description='Invalid search query')

    # Use literal string matching, not glob patterns
    query_lower = query.lower()
    results = []
    for f in search_base.rglob('*'):
        if query_lower in f.name.lower():
            if f.suffix.lower() in ALLOWED_EXTENSIONS and not f.is_symlink():
                rel = f.relative_to(DOCUMENT_ROOT)
                results.append(str(rel))

    return jsonify({'results': results[:100]})

